export const sourceCode = "# Sizing\n\n### Size Presets\n\nUse the `size` option for convenient preset sizes:\n\n```javascript\nimport { createSvgString, Alarm } from '@boxicons-pro/js';\n\ncreateSvgString(Alarm, { size: 'xs' });   // 16px\ncreateSvgString(Alarm, { size: 'sm' });   // 20px\ncreateSvgString(Alarm, { size: 'base' }); // 24px (default)\ncreateSvgString(Alarm, { size: 'md' });   // 36px\ncreateSvgString(Alarm, { size: 'lg' });   // 48px\ncreateSvgString(Alarm, { size: 'xl' });   // 64px\ncreateSvgString(Alarm, { size: '2xl' });  // 96px\ncreateSvgString(Alarm, { size: '3xl' });  // 128px\ncreateSvgString(Alarm, { size: '4xl' });  // 256px\ncreateSvgString(Alarm, { size: '5xl' });  // 512px\n```\n\n### Custom Sizing\n\nFor custom sizes, use `width` and `height` options (overrides `size`):\n\n```javascript\ncreateSvgString(Alarm, { width: 32, height: 32 });\ncreateSvgString(Alarm, { width: '48', height: '48' });\ncreateSvgString(Alarm, { width: '2rem', height: '2rem' });\n```";
